{
  "query": "{
    trip(
      from: { place: "{{STOP_SINSENVEIEN}}" }
      to:   { place: "{{STOP_VISPERUD}}" }
      numTripPatterns: 5
    ) {
      tripPatterns {
        duration
        expectedStartTime
        expectedEndTime
        legs {
          mode
          fromPlace { name }
          toPlace   { name }
          fromEstimatedCall {
            aimedDepartureTime
            expectedDepartureTime
          }
          line { publicCode }
        }
      }
    }
  }"
}

